# ---- NOT BOUND: the operand stays the ROM's, the binding is declared pending ----------------------------------------------
def test_the_handler_s_operand_stays_the_rom_s_and_no_word_of_a_blob_names_our_table(blob):
    """NOTHING IS BOUND BY SLICE T: the operand of the handler gem_entry copies holds the ROM's table in each blob's
    own bytes; no longword of a blob holds our table's address; and the binding is DECLARED PENDING, by name, with
    the slice it waits for — in the generator, the registry's own pending list being pinned empty."""
    pending = linef_table.PENDING_BINDING
    assert (pending.symbol, pending.offset, pending.holds, pending.will_hold) == (HANDLER, aes.LINEF_TABLE_OPERAND, aes.AES_LINEF_TABLE, TABLE)
    assert "slice B" in pending.waits_for
    assert long_of(blob, blob.entry(pending.symbol) + pending.offset) == pending.holds
    ours = blob.entry(TABLE).to_bytes(LONG_BYTES, "big")
    naming = [blob.base + at for at in range(0, len(blob.blob) - LONG_BYTES + 1, WORD_BYTES) if blob.blob[at:at + LONG_BYTES] == ours]
    assert not naming, f"a word of the blob names our table: {[hex(at) for at in naming]}"
    assert not any("LINEF" in declared.upper() or "LINE-F" in declared.upper() for declared in aes_event.DECLARED_NOT_YET_MAPPED_AT_TIER3)


# ---- EVERY THUNK IS ITS ROUTINE'S SIGNATURE, read off the blob's bytes -----------------------------------------------------
# The instructions a thunk is made of, as the 68000 words they are, and what each costs on a 68000 (cycles).
MOVE_L_DISPLACED_SP_PUSH = 0x2F2F       # move.l  d16(sp),-(sp)
MOVE_L_AT_SP_PUSH = 0x2F17              # move.l  (sp),-(sp)
MOVEA_W_DISPLACED_SP_A0 = 0x306F        # movea.w d16(sp),a0        (sign-extends)
MOVE_L_A0_PUSH = 0x2F08                 # move.l  a0,-(sp)
PEA_ABSOLUTE_SHORT = 0x4878             # pea     (xxx).w
JSR_ABSOLUTE_LONG = 0x4EB9
LEA_DISPLACED_SP_SP = 0x4FEF            # lea     d16(sp),sp
RTS = 0x4E75
RTS_CYCLES, JSR_CYCLES, LEA_CYCLES, PEA_CYCLES = 16, 20, 8, 16
LONG_PUSH_CYCLES, WORD_PUSH_CYCLES, INDIRECT_PUSH_CYCLES = 24, 12 + 12, 20
SLOT_BYTES, RETURN_ADDRESS_BYTES = LONG_BYTES, LONG_BYTES
LONG, WORD, RETURN_SITE, IMAGE = "a longword", "a word, sign-extended", "the return site", "the image base"
RETURN_SITE_AT_SP = "the return site, at the stack pointer"      # ...of a routine with no other argument: `(sp)`, four cycles less
KIND_OF = {vdi.LONG_ARG: LONG, vdi.WORD_ARG: WORD}
PUSH_CYCLES = {LONG: LONG_PUSH_CYCLES, WORD: WORD_PUSH_CYCLES, RETURN_SITE: LONG_PUSH_CYCLES, RETURN_SITE_AT_SP: INDIRECT_PUSH_CYCLES,
               IMAGE: PEA_CYCLES}
Thunk = namedtuple("Thunk", "pushes calls dropped")
Thunk.__doc__ = """A thunk as its bytes read: `pushes` — `(what, the offset in the caller's frame it is read from)` in the
order pushed (None the offset of the return site and the image) —, the address it `calls`, the bytes it drops after."""


def read_thunk(blob, name):
    """`name`'s thunk in `blob`, decoded from its own bytes to its `rts` — refused at the first word that is none of
    a thunk's instructions, and where the `rts` is not the symbol's last word."""
    symbol = symbols_of(blob)[name]
    code = blob.blob[symbol.start - blob.base:symbol.start - blob.base + symbol.size]
    words = struct.unpack(f">{len(code) // WORD_BYTES}H", code)
    pushes, at, pushed = [], 0, 0

    def from_the_frame(displacement):
        return displacement - pushed - RETURN_ADDRESS_BYTES

    while words[at] != JSR_ABSOLUTE_LONG:
        if words[at] == MOVE_L_AT_SP_PUSH and not pushed:
            pushes.append((RETURN_SITE_AT_SP, None))
            at += 1
        elif words[at] == MOVE_L_DISPLACED_SP_PUSH:
            pushes.append((RETURN_SITE, None) if words[at + 1] == pushed else (LONG, from_the_frame(words[at + 1])))
            at += 2
        elif words[at:at + 3:2] == (MOVEA_W_DISPLACED_SP_A0, MOVE_L_A0_PUSH):
            pushes.append((WORD, from_the_frame(words[at + 1])))
            at += 3
        elif words[at:at + 2] == (PEA_ABSOLUTE_SHORT, 0):
            pushes.append((IMAGE, None))
            at += 2
        else:
            raise AssertionError(f"{name}: the word ${words[at]:04x} at +{at * WORD_BYTES} begins no instruction of a thunk")
        pushed += SLOT_BYTES
    calls = words[at + 1] << 16 | words[at + 2]
    at += 3
    dropped = 0
    if words[at] == LEA_DISPLACED_SP_SP:
        dropped, at = words[at + 1], at + 2
    assert words[at:] == (RTS,), f"{name}: after its call and its drop lie {[hex(word) for word in words[at:]]}, not one `rts`"
    return Thunk(tuple(pushes), calls, dropped)


def signature_pushes(routine):
    """What `routine`'s declared signature makes its thunk push, in order: the frame's arguments LAST FIRST — each
    from its own place in the caller's frame, at its own width —, the host arguments, the image."""
    signature, framed, at = vdi.ALCYON[routine], [], 0
    for argtype in vdi.frame_argtypes(routine):
        framed.append((KIND_OF[argtype], at))
        at += vdi.ARG_BYTES[argtype]
    hosts = [(RETURN_SITE if framed or nth else RETURN_SITE_AT_SP, None) for nth in range(signature.host_arguments)]
    return (*reversed(framed), *hosts, *(((IMAGE, None),) if vdi.takes_image(routine) else ()))


def price_of(thunk):
    """What one call through `thunk` costs in its own instructions, on a 68000."""
    return sum(PUSH_CYCLES[what] for what, _at in thunk.pushes) + JSR_CYCLES + (LEA_CYCLES if thunk.dropped else 0) + RTS_CYCLES


THUNKED = linef_table.thunked_routines()


def test_every_thunk_is_its_routine_s_declared_signature_read_off_its_bytes(blob):
    """Each of the 299: every argument read from its own offset of the caller's frame, at its declared width, a WORD
    sign-extended, pushed last first; the return site for a core that takes one; the
    image base for a core that takes one; the core IT IS NAMED FOR called; exactly what it pushed dropped."""
    wrong = []
    for routine in THUNKED:
        name, core = linef_table.thunk_symbol(routine), routines.core_symbol(routine)
        thunk, pushes = read_thunk(blob, name), signature_pushes(routine)
        if thunk != Thunk(pushes, blob.entry(core), len(pushes) * SLOT_BYTES):
            wrong.append(f"{name} pushes {thunk.pushes}, calls ${thunk.calls:x} and drops {thunk.dropped}: its signature says "
                         f"{pushes}, {core} (${blob.entry(core):x}) and {len(pushes) * SLOT_BYTES}")
    assert not wrong, f"{len(wrong)} thunks are not their signature's: {wrong[:4]}"
    assert len(THUNKED) == THUNKS == len(set(map(routines.core_symbol, THUNKED)))


def test_the_reader_tells_a_width_an_extension_an_order_and_a_return_site_apart(blob):
    """ITS REDS, on the reader itself: a word and a longword, two arguments' order and the return site are different
    readings — and the declared signatures hold every one of the shapes (no routine of the table declares a
    `uint16_t` argument: the generator refuses one, and the reader reads none)."""
    kinds = Counter(what for routine in THUNKED for what, _at in signature_pushes(routine))
    assert kinds[LONG] and kinds[WORD] and kinds[RETURN_SITE] and kinds[RETURN_SITE_AT_SP] and kinds[IMAGE]
    assert not any(argtype is vdi.UWORD_ARG for routine in THUNKED for argtype in vdi.frame_argtypes(routine))
    name = linef_table.thunk_symbol("AES_ROM_OB_ADD")
    assert read_thunk(blob, name).pushes == ((WORD, 6), (WORD, 4), (LONG, 0), (IMAGE, None))
    hosted = read_thunk(blob, linef_table.thunk_symbol("AES_ROM_DOS_SDRV"))
    assert hosted.pushes == ((WORD, 0), (RETURN_SITE, None), (IMAGE, None))
    assert read_thunk(blob, linef_table.thunk_symbol("AES_ROM_DOS_GDRV")).pushes == ((RETURN_SITE_AT_SP, None), (IMAGE, None))


# ---- ENTERED: a routine's own case, on the blob, THROUGH THE TABLE --------------------------------------------------------
# THE LABELLED STAGING: the machine is the row's own (the ROM-booted snapshot and the case's pokes); the harness lays
# ONE LONGWORD in OUR run's copy of it — the operand of the Line-F handler's RAM copy, our table's address — enters
# both shores at the Line-F caller with the routine's own call word, and puts the ROM's operand back before the two
# machines are compared. Nothing else is staged: the frame is the case's, and what reaches the core went through the
# ROM's handler, our table and our thunk.
ALCYON_KEEPS = ("d3", "d4", "d5", "d6", "d7", "a3", "a4", "a5", "a6")       # what an Alcyon callee owes its caller back
RETURNS = {aes.WORD_ANSWER: tier3.RETURNS_WORD, aes.LONG_ANSWER: tier3.RETURNS_LONG, None: tier3.RETURNS_NOTHING}


class _EnteredAtTheLineFCaller(rom_bench.RomBench):
    """The kit's call of our build, ENTERED AT THE STAGED LINE-F CALLER over the case's own frame, with the handler
    copy's operand staged at our table for the run and the ROM's put back after it (while `through_the_table`)."""

    through_the_table = False

    def _call(self, image, symbol, args=(), **kwargs):
        if not self.through_the_table:
            return super()._call(image, symbol, args, **kwargs)
        operand = slice(TABLE_OPERAND_IN_RAM, TABLE_OPERAND_IN_RAM + LONG_BYTES)
        assert bytes(image[operand]) == THE_ROM_S_OPERAND, "the machine's handler copy does not load the ROM's table"
        staged = self.entry(TABLE).to_bytes(LONG_BYTES, "big")
        image[operand] = staged
        ours = super()._call(image, symbol, (case.long_in(image, abi.FIRST_ARG),), entry_at=aes.LINE_F_CALLER_AT, **kwargs)
        assert bytes(ours.image[operand]) == staged, "our run stored over the staged operand"
        ours.image[operand] = THE_ROM_S_OPERAND
        return ours


class ThroughTheTable(tier3.RomBench, _EnteredAtTheLineFCaller):
    """Tier 3's bench (its relocations at entry and back), our run entered through the table."""

    def entered(self, entered_case):
        """`entered_case` on both shores: the ROM's own run through its call word, then ours through the table."""
        routine, name, pokes, regs, psg_seed, io_seed, schedule, dropped, returns = entered_case
        symbol = routines.core_symbol(routine)
        frame = make_image(pokes)[abi.FIRST_ARG:]
        formats = "".join(vdi.FRAME_FORMATS.get(argtype, "H") for argtype in vdi.frame_argtypes(routine))
        handed = (0,) * vdi.takes_image(routine) + struct.unpack_from(">" + formats, frame)

        def run_ours(image):
            return self._call(image, symbol, handed, io_seed=rom_bench._bench_io_seed(io_seed), schedule=schedule)

        def vet_ours(ours, original_registers):
            rom_bench._vet_return_value(symbol, ours.d0, original_registers["d0"], returns)
            lost = {name: hex(ours.regs[name]) for name in ALCYON_KEEPS if ours.regs[name] != rom_bench.CALLEE_SAVED_SEEDS[name]}
            assert not lost, f"{symbol}, through its thunk, came back with {lost}: registers an Alcyon caller keeps"

        self._vet_pokes_are_clear_of_the_blob(symbol, pokes)
        self.through_the_table = True
        try:
            return self._both_sides(aes.LINE_F_CALLER_AT, symbol, dict(regs), pokes, (psg_seed, None, io_seed), run_ours, vet_ours,
                                    (0, 0), schedule=schedule, dropped=dropped)
        finally:
            self.through_the_table = False


@functools.cache
def through(blob_name):
    return ThroughTheTable(*([BLOBS[blob_name]] if BLOBS[blob_name] else []))


EnteredCase = namedtuple("EnteredCase", "routine name pokes regs psg_seed io_seed schedule dropped returns")
# WHY A REGISTERED CASE OF A ROUTINE CANNOT BE ENTERED THIS WAY — each a property of the case, read off the registry.
STOPS_SHORT = "a checkpoint: the case stops before the routine returns"
INTERRUPTED = "taken through interrupts: its deliveries are laid by a measurement's own watch"
ITS_DROPS = "its drops need the measurement's own arrangement (a stack put back, the X flag, the screen manager made ours)"
ENTRY_REGISTERS = "entered with registers of its caller's beside the frame, which no thunk hands a C core"
NO_CASE = "no registered case is entered at the routine"
# THREE GLUE ENTRIES HAVE NO REGISTERED CASE OF THEIR OWN (their batteries run them unregistered; Tier 3 prices them
# inside their callers) — and each takes its caller's return site, which is this module's to hold. A LABELLED ARGUMENT
# CLASS, STAGED HERE: the frame of `arguments` over ITS BATTERY'S OWN recording, scripted `trap #1` — the handler that
# knows how long that function's frame is (the shell's for the file calls, the file selector's replay for Cconout:
# above a frame lies its caller's stack, which no build reproduces) — GEMDOS answering 0, nothing dropped.
STAGED_HERE = "an argument class staged here over the scripted trap"
A_HANDLE, AN_ADDRESS, GEMDOS_ANSWERS_0 = 6, aes_gemdosif.PATH_AT, 0
ArgumentClass = namedtuple("ArgumentClass", "arguments machine")
ARGUMENT_CLASSES = {
    "AES_ROM_DOS_SDTA": ArgumentClass((AN_ADDRESS,), lambda: aes_shell.scripted_machine((GEMDOS_ANSWERS_0,))),
    "AES_ROM_DOS_CLOSE": ArgumentClass((A_HANDLE,), lambda: aes_shell.scripted_machine((GEMDOS_ANSWERS_0,))),
    "AES_ROM_DOS_CCONOUT": ArgumentClass((addrs.CON_BEL,), lambda: aes_fslib.replay_pokes(((GEMDOS_ANSWERS_0, aes_fslib.NO_DTA),))),
}


def _staged_here(routine):
    staged = ARGUMENT_CLASSES[routine]
    pokes = merge_pokes(staged.machine(), aes.alcyon_frame(routine, *staged.arguments), aes.line_f_caller_pokes(routine))
    return EnteredCase(routine, f"{routines.core_symbol(routine)}, {STAGED_HERE}", pokes, {}, None, None, (), (),
                       RETURNS[vdi.ALCYON[routine].restype])


def _why_not(row, dropped):
    name, _entry, regs, _pokes, _psg, _io, _schedule, stop_pc = test_boot_snapshot.fields(row)
    if stop_pc:
        return STOPS_SHORT
    if test_boot_snapshot.delivered_of(row) or name in aes_event.SLICED_ROWS:
        return INTERRUPTED
    # (A HANDLER'S ROW MEASURED AT ITS ARRIVAL, `aes_ctlmgr.HANDLED`, is no reason: where it is measured is Tier 3's
    # choice for its PRICE — the case is a registered call over a staged frame all the same, and is entered here as
    # any other: hctl_rect and hctl_window each by their first case that takes no interrupt. Reviewer A's finding.)
    if tier3.put_back_for(dropped) or aes_takeover.named_in(dropped) or any(drop in tier3.aes_switching.THE_X_FLAG_ALONE for drop in dropped):
        return ITS_DROPS
    if set(regs) & (set(ALCYON_KEEPS) | {"d2", "a2"}):
        return ENTRY_REGISTERS
    return None


@functools.cache
def _cases_by_entry():
    by_entry = {}
    for row in tuple(test_boot_snapshot.VERIFIED_CASES) + tuple(test_boot_snapshot.UNPRICED_CASES):
        by_entry.setdefault(test_boot_snapshot.fields(row)[1], []).append(row)
    return by_entry


@functools.cache
def entered_cases():
    """`({routine: the case it is entered by}, {routine: why none})` over the 299 — each routine's FIRST registered
    case (priced or not) that is entered at the routine itself and can be entered through the caller."""
    return _first_enterable_cases(tuple(THUNKED))


def _first_enterable_cases(asked):
    by_entry = _cases_by_entry()
    chosen, refused = {}, {}
    for routine in asked:
        reasons = []
        for row in by_entry.get(getattr(addrs, routine), ()):
            name, _entry, regs, pokes, psg_seed, io_seed, schedule, _stop = test_boot_snapshot.fields(row)
            dropped = tier3.DROPPED.get(name, ())
            why = _why_not(row, dropped)
            if why is None:
                returns = tier3.RETURNS_NOTHING if name in tier3.UNANSWERED else RETURNS[vdi.ALCYON[routine].restype]
                through_the_caller = merge_pokes(pokes, aes.line_f_caller_pokes(routine))
                chosen[routine] = EnteredCase(routine, name, through_the_caller, regs, psg_seed, io_seed, schedule, dropped, returns)
                break
            reasons.append(why)
        else:
            if not reasons and routine in ARGUMENT_CLASSES:
                chosen[routine] = _staged_here(routine)
            else:
                refused[routine] = sorted(set(reasons)) or [NO_CASE]
    staged = set(ARGUMENT_CLASSES) & set(asked)
    assert staged <= set(chosen) and all(chosen[routine].name.endswith(STAGED_HERE) for routine in staged), (
        "a routine with an argument class staged here has a registered case now: enter it by that, and drop the class")
    return chosen, refused


def rom_span_entered(target):
    """The cycles the profiled run spent AT the ROM routine's first instruction: none unless it was entered. (For a
    run in which the ROM's desk runs by declaration — the staged our-boot: a case entered through the table is held
    to the whole text, `rom_gem_text_cycles`.)"""
    return emu.prof_cycles(target, target + WORD_BYTES)


def rom_gem_text_cycles():
    """The cycles the profiled run spent ANYWHERE IN THE ROM'S GEM TEXT, `[gem_entry, the Line-F table)` — the whole
    text, not the entered routine's first word: a run through the table that reached ANY ROM routine (the one asked
    past its first instruction, a callee the table left the ROM's) is no run of ours. The handler runs as its RAM
    copy, outside this span. (Reviewer A read it 0 over every entered case of both blobs.)"""
    return emu.prof_cycles(*aes.AES_TEXT)


# THE READER'S OWN RED: a cycle spent MID-ROUTINE in the ROM's GEM text — a `jsr` from a stub to an `rts` that is no
# routine's first word — is read by the whole-text reader and by no reader of first words.
JSR_ABSOLUTE_LONG, RTS = 0x4EB9, 0x4E75
STUB_AT = staging.POINTER_ARGUMENTS


def _an_rts_inside_a_routine():
    """The first `rts` of the ROM's GEM text that no entry of the Line-F table names: an instruction inside a routine."""
    entered_by_the_table = set(aes._line_f_call_index())
    return next(at for at in range(*aes.AES_TEXT, WORD_BYTES) if case.word_in(BASE_IMAGE, at) == RTS and at not in entered_by_the_table)


def test_the_who_ran_reader_sees_a_cycle_anywhere_in_the_rom_s_gem_text_not_at_a_routine_s_first_word_alone():
    inside = _an_rts_inside_a_routine()
    stub = struct.pack(">HIH", JSR_ABSOLUTE_LONG, inside, RTS)
    aes_event.vet_the_profile_is_free("the who-ran reader's own red")
    emu.prof_reset()
    emu.prof_enable(True)
    try:
        emu.run(make_image({STUB_AT: stub}), STUB_AT)
    finally:
        emu.prof_enable(False)
    assert rom_gem_text_cycles() == RTS_CYCLES, "the planted `rts` inside the ROM's GEM text was not read"
    assert not any(rom_span_entered(getattr(addrs, routine)) for routine in THUNKED), "...and it is no thunked routine's first word"


ENTERED = sorted(entered_cases()[0])
THE_SHIPPED_BLOB, THE_BENCH_BLOB = "the shipped blob", "the bench blob"
assert set(BLOBS) == {THE_SHIPPED_BLOB, THE_BENCH_BLOB}


def entered_on():
    """`[(routine, blob)]`: every entered routine ON THE SHIPPED BLOB — what ships — and on the bench blob too UNLESS
    ITS C REACHES A TRANSCRIBED CORE (T→): there the bench blob runs the C twin of a routine that ships as its `.S`,
    which Tier 3 itself prices on the shipped blob alone (a return site parked from the twin, the twin's flags)."""
    through_a_call = tier3._reaching_transcribed_cores()
    return [(routine, name) for routine in ENTERED for name in (THE_SHIPPED_BLOB, THE_BENCH_BLOB)
            if name == THE_SHIPPED_BLOB or routines.core_symbol(routine) not in through_a_call]


ENTERED_ON = entered_on()


def _entered_id(routine, blob_name):
    """A case's id: the routine and the blob — and, for the three with no registered case, THAT ITS ARGUMENTS ARE A
    CLASS STAGED HERE (the id is what a reader of a run sees)."""
    return f"{routine}{' (AN ARGUMENT CLASS STAGED HERE)' if routine in ARGUMENT_CLASSES else ''}-{blob_name}"


@pytest.mark.parametrize("routine, blob_name", ENTERED_ON, ids=[_entered_id(routine, name) for routine, name in ENTERED_ON])
def test_a_thunk_is_entered_by_its_routine_s_own_case_through_the_table_a_labelled_staging(routine, blob_name):
    """THE ROM'S CALL WORD -> THE ROM'S HANDLER -> OUR TABLE -> OUR THUNK -> OUR CORE, against the ROM's own run of the
    same case through the same word: the same machine after it (but the row's own drops), the same answer, the
    registers an Alcyon caller keeps. WHO RAN, off our run's profile: NO CYCLE ANYWHERE IN THE ROM'S GEM TEXT, the
    handler's copy run, the thunk entered EXACTLY ONCE and its cycles its own instructions', the core entered."""
    bench, entered_case = through(blob_name), entered_cases()[0][routine]
    word = aes.line_f_call_word(routine)
    index = (word & aes.LINEF_OFFSET_MASK) // LONG_BYTES
    thunk = symbols_of(bench)[linef_table.thunk_symbol(routine)]
    assert table_of(bench)[index] == thunk.start, "the word the case calls by does not name this routine's thunk"
    bench.entered(entered_case)
    core = bench.entry(routines.core_symbol(routine))
    assert not rom_gem_text_cycles(), f"THE ROM'S GEM TEXT RAN in our run of {routine}: {rom_gem_text_cycles()} cycles"
    assert emu.prof_cycles(aes.AES_LINEF_COPY, aes.AES_LINEF_COPY + aes.LINEF_COPY_BYTES), "the Line-F handler's copy never ran"
    calls = emu.prof_cycles(thunk.start + thunk.size - WORD_BYTES, thunk.start + thunk.size) // RTS_CYCLES
    assert calls == 1 and emu.prof_cycles(core, core + WORD_BYTES), f"{thunk.name} was entered {calls} times, or its core never"
    assert emu.prof_cycles(thunk.start, thunk.start + thunk.size) == price_of(read_thunk(bench, thunk.name))


# THE THUNKS NO REGISTERED CASE CAN ENTER — BY NAME, never assumed entered. Each a routine every one of whose cases is
# of a kind the caller's entry cannot make (above), with the kinds; held EXACT both ways: a case that makes one
# enterable, or one that stops being so, reds until this list says it.
UNENTERED = {
    "AES_ROM_ALL_RUN": [INTERRUPTED], "AES_ROM_AP_TPLAY": [INTERRUPTED], "AES_ROM_AP_TRECD": [INTERRUPTED],
    "AES_ROM_DESK_FREE": [INTERRUPTED], "AES_ROM_DESK_RSRC_FREE": [INTERRUPTED], "AES_ROM_EV_TIMER": [INTERRUPTED],
    "AES_ROM_GEM_READ_INF": [NO_CASE],      # priced as a stretch of the build's own boot, between two checkpoints
}
ENTERED_THUNKS = 292                    # of the 299: THUNKS less the seven above


def test_the_thunks_no_case_enters_are_listed_by_name():
    _chosen, refused = entered_cases()
    assert refused == UNENTERED, (
        f"UNENTERED is not what the registry says: now enterable {sorted(set(UNENTERED) - set(refused))}, "
        f"unlisted {{ {', '.join(f'{name!r}: {why!r}' for name, why in sorted(refused.items()) if UNENTERED.get(name) != why)} }}")
    assert len(ENTERED) + len(UNENTERED) == THUNKS and len(ENTERED) == ENTERED_THUNKS
    for handler in ("AES_ROM_HCTL_RECT", "AES_ROM_HCTL_WINDOW"):    # ...each by a case its row measures at its arrival
        assert entered_cases()[0][handler].name in aes_ctlmgr.HANDLED


# ---- THE NATIVE ENTRIES, ENTERED THE SAME WAY ------------------------------------------------------------------------------
# 82 entries of the table are OURS NATIVELY — a byte-pinned `.S` entry or an Alcyon entry, 64 routines — and need no
# thunk: the table's longword IS the entry. Each that HAS A DECLARED ALCYON SIGNATURE AND A REGISTERED CASE AT ITS
# ENTRY is entered as a thunk is — the ROM's call word, the ROM's handler, our table — on the shipped blob (what ships:
# a `.S` entry is the routine there), against the ROM's own run: who-ran the same, the entry's first instruction run.
# THE REST ARE LISTED BY NAME WITH THE REASON, exact both ways (reviewer A's measurement: 51 enterable, 9 + 3 + 1 not).
NO_SIGNATURE = "no declared Alcyon signature: entered by registers, by a trap or by a jump — never over a frame a case stages"
NO_ROW_AT_ITS_ENTRY = "no registered case is entered at the entry"
A_CODE_ADDRESS_BY_VALUE = ("RED when forced (reviewer A): the two machines differ in a code address stored by value — the ROM's "
                           "$fe39ce, the blob's own — at two longwords; its row maps it, a run entered at the caller does not")
NATIVES_NOT_ENTERED_BY_NAME = {"AES_ROM_PGMLD": A_CODE_ADDRESS_BY_VALUE}
NATIVE_ROUTINES, NATIVES_ENTERED = 64, 51


@functools.cache
def native_routines():
    """`{the entry's symbol: the `addrs.h` routine it is declared under, or None}` over the table's native entries."""
    declared = {getattr(addrs, name): name for name in vdi.ALCYON}
    return {entry.symbol: declared.get(entry.target) for entry in linef_table.entries() if entry.verdict == OURS_NATIVE}


@functools.cache
def native_cases():
    """`({symbol: (routine, the case it is entered by)}, {symbol: why none})` over the 64 native routines."""
    natives = native_routines()
    declared = tuple(routine for routine in natives.values() if routine is not None and routine not in NATIVES_NOT_ENTERED_BY_NAME)
    chosen, refused = _first_enterable_cases(declared)
    entered, unentered = {}, {}
    for symbol, routine in natives.items():
        if routine in chosen:
            entered[symbol] = (routine, chosen[routine])
        else:
            unentered[symbol] = ([NO_SIGNATURE] if routine is None else [NATIVES_NOT_ENTERED_BY_NAME[routine]]
                                 if routine in NATIVES_NOT_ENTERED_BY_NAME else refused[routine])
    return entered, unentered


NATIVES_UNENTERED = {
    "aes_rom_gem_gemdos_call": [NO_SIGNATURE], "aes_dsptch": [NO_SIGNATURE], "aes_rom_spl7_save": [NO_SIGNATURE],
    "aes_rom_spl_restore": [NO_SIGNATURE], "aes_rom_cli": [NO_SIGNATURE], "aes_rom_sti": [NO_SIGNATURE],
    "aes_rom_savestate": [NO_SIGNATURE], "aes_rom_switchto": [NO_SIGNATURE], "aes_rom_trap2_exit": [NO_SIGNATURE],
    "aes_rom_pgmld": [A_CODE_ADDRESS_BY_VALUE],
}


NATIVES_WITHOUT_A_ROW = ["aes_rom_crit_err", "aes_rom_dos_exec", "aes_rom_drawrat"]   # (`NO_CASE`: held inside their callers' rows, or as a `.S` row)


def test_the_native_entries_no_case_enters_are_listed_by_name():
    entered, unentered = native_cases()
    listed = {symbol: why for symbol, why in unentered.items() if why != [NO_CASE]}
    without_a_row = sorted(symbol for symbol, why in unentered.items() if why == [NO_CASE])
    assert listed == NATIVES_UNENTERED, f"not what the registry says: {sorted(set(listed) ^ set(NATIVES_UNENTERED))}"
    assert without_a_row == NATIVES_WITHOUT_A_ROW, without_a_row
    assert (len(native_routines()), len(entered)) == (NATIVE_ROUTINES, NATIVES_ENTERED)


NATIVES_ENTERED_BY = sorted(native_cases()[0])


@pytest.mark.parametrize("symbol", NATIVES_ENTERED_BY)
def test_a_native_entry_is_entered_by_its_routine_s_own_case_through_the_table_a_labelled_staging(symbol):
    """THE ROM'S CALL WORD -> THE ROM'S HANDLER -> OUR TABLE -> OUR ENTRY ITSELF, on the shipped blob, against the ROM's
    own run of the same case: the same machine, the same answer; no cycle anywhere in the ROM's GEM text, the
    handler's copy run, the entry's first instruction run."""
    bench = through(THE_SHIPPED_BLOB)
    routine, entered_case = native_cases()[0][symbol]
    index = (aes.line_f_call_word(routine) & aes.LINEF_OFFSET_MASK) // LONG_BYTES
    entry = bench.entry(symbol)
    assert table_of(bench)[index] == entry, "the word the case calls by does not name this entry"
    bench.entered(entered_case)
    assert not rom_gem_text_cycles(), f"THE ROM'S GEM TEXT RAN in our run of {routine}: {rom_gem_text_cycles()} cycles"
    assert emu.prof_cycles(aes.AES_LINEF_COPY, aes.AES_LINEF_COPY + aes.LINEF_COPY_BYTES), "the Line-F handler's copy never ran"
    assert emu.prof_cycles(entry, entry + WORD_BYTES), f"{symbol} was not entered"


# ---- THE CORES HANDED THEIR CALLER'S RETURN SITE --------------------------------------------------------------------------
HOSTED = sorted(routine for routine in THUNKED if vdi.ALCYON[routine].host_arguments)
# Where the Line-F caller's call word returns: the site the ROM's glue parks, and the one a thunk must hand.
LINE_F_RETURN_SITE = aes.LINE_F_CALLER_AT + len(DROP_STACK_LONG) + WORD_BYTES


def test_the_cores_that_take_a_return_site_are_the_seven_glue_entries_and_each_is_entered():
    """Ten cores declare a host argument; seven are thunked — GEMDOS glue entries, each parking its caller's return
    site —, two ship as their `.S` (dos_exec, trp14: native entries, the ROM's own pop) and one is the VDI's, no
    Line-F target. Every one of the seven has a case that enters it (above): none is unentered."""
    declared = {name for name, signature in vdi.ALCYON.items() if signature.host_arguments}
    # ---- band 6 wave 1a, unit O ---- seven more cores take a return site (the desk's glue entries through `$fe3c28`,
    # dos_rename and the BIOS door trp13): WRITTEN, LINKED AND NOT FLIPPED — no thunk is made for one until its flip.
    not_flipped = {name for name in declared if name in linef_table.LINKED_AND_NOT_FLIPPED}
    assert not_flipped == {"AES_ROM_DOS_RENAME", "AES_ROM_DOS_RAWCIO", "AES_ROM_DOS_CHMOD", "AES_ROM_DOS_DELETE", "AES_ROM_DOS_RMDIR",
                           "AES_ROM_DOS_CREATE", "AES_ROM_TRP13"}
    declared -= not_flipped
    # ---- end of unit O's ----
    natives = {entry.target for entry in linef_table.entries() if entry.verdict == OURS_NATIVE}
    assert len(declared) == 10 and len(HOSTED) == 7
    assert {name for name in declared - set(HOSTED) if getattr(addrs, name) in natives} == {"AES_ROM_DOS_EXEC", "AES_ROM_TRP14"}
    assert declared - set(HOSTED) - {"AES_ROM_DOS_EXEC", "AES_ROM_TRP14"} == {"VDI_ROM_GEMDOS_CALL"}
    assert set(HOSTED) <= set(ENTERED)


HOSTED_ON = [(routine, name) for routine, name in ENTERED_ON if routine in HOSTED]


@pytest.mark.parametrize("routine, blob_name", HOSTED_ON, ids=[f"{routine}-{name}" for routine, name in HOSTED_ON])
def test_a_glue_entry_s_thunk_hands_the_real_return_site_through_the_table_a_labelled_staging(routine, blob_name):
    """The site a glue entry parks is THE WORD AFTER THE CALLER'S CALL WORD: the ROM's run through the caller parks it
    (read where its ledger stored it), and so does ours — the machines equal there, undropped."""
    bench, entered_case = through(blob_name), entered_cases()[0][routine]
    site = LINE_F_RETURN_SITE.to_bytes(LONG_BYTES, "big")
    _final, writes, _registers = emu.run(make_image(entered_case.pokes), aes.LINE_F_CALLER_AT, dict(entered_case.regs),
                                         psg_seed=entered_case.psg_seed, io_seed=entered_case.io_seed, schedule=entered_case.schedule)
    stored = case.written_by(writes)
    parked = [at for at in sorted(stored) if all(stored.get(at + byte) == site[byte:byte + 1] for byte in range(LONG_BYTES))]
    assert parked, f"the ROM's {routine}, called through the caller, parks its return site nowhere"
    assert not any(lo < at + LONG_BYTES and at < hi for at in parked for lo, hi, _why in entered_case.dropped), "the park is dropped: nothing would hold it"
    bench.entered(entered_case)


# ---- WHAT THE ORACLE CANNOT ENTER (slice H's finding) ----------------------------------------------------------------------
# The kit's 68000 executes `$F620..$F627` as the 68040's MOVE16 and takes no Line-F exception. The entries those call
# words name cannot be entered through the handler by their own word on this oracle (outside `aes_boot.continued`,
# which stands in for the exception by hand): held by the table's bytes (above), and BY NAME here.
UNENTERED_BY_THE_ORACLE = {0xF620: 0xFE16E6, 0xF624: 0xFDFEBC}


def test_the_two_entries_the_oracle_s_move16_words_name_are_the_rom_s_and_no_entry_of_ours_is_called_by_one():
    words = [word for word in aes_boot.ORACLE_S_MOVE16_WORDS if not word & aes.LINEF_RETURN_BIT and not word % LONG_BYTES]
    table = linef_table.entries()
    named = {word: table[(word & aes.LINEF_OFFSET_MASK) // LONG_BYTES] for word in words}
    assert {word: entry.target for word, entry in named.items()} == UNENTERED_BY_THE_ORACLE
    assert all(entry.verdict == THE_ROM_S for entry in named.values())
    assert all([other.index for other in table if other.target == entry.target] == [entry.index] for entry in named.values())
    in_the_text = {case.word_in(BASE_IMAGE, at): at for at in range(*aes.AES_TEXT, WORD_BYTES)
                   if case.word_in(BASE_IMAGE, at) in aes_boot.ORACLE_S_MOVE16_WORDS}
    assert set(in_the_text) == set(UNENTERED_BY_THE_ORACLE), "another word of the GEM text is one the oracle executes"
    for routine in ENTERED:
        assert aes.line_f_call_word(routine) not in aes_boot.ORACLE_S_MOVE16_WORDS


# ---- THE STAGED OUR-BOOT OVER THE TABLE, to the desk's first idle ---------------------------------------------------------
# THE LABELLED STAGING: the blob's own bytes with ONE operand laid by the harness before the blob is — the handler
# gem_entry copies loads OUR table — and then the our-boot machine as it is (`aes_boot.booted(..., laid=AT_GEM_ENTRY)`:
# the blob laid at the pre-init stop, the run entered at its own gem_entry). Every other longword is the run's own.
OurBootOverTheTable = namedtuple("OurBootOverTheTable", "boot in_the_blob in_the_rom_s_gem_text in_the_copy in_the_copy_s_tail in_thunks "
                                                        "thunks_entered rom_routines_of_ours_entered move16_sites")
HANDLER_BYTES = aes.AES_LINEF_TABLE - addrs.AES_ROM_LINEF_HANDLER      # the handler itself: the copy's tail lies behind it


def staged_for_an_our_boot(blob):
    """`blob` as an our-boot lays it (`aes_boot.Ours`), its handler's operand STAGED at its own table."""
    ours = aes_boot.ours_of(blob)
    at = blob.entry(HANDLER) - blob.base + aes.LINEF_TABLE_OPERAND
    assert ours.image[at:at + LONG_BYTES] == THE_ROM_S_OPERAND
    return ours._replace(image=ours.image[:at] + blob.entry(TABLE).to_bytes(LONG_BYTES, "big") + ours.image[at + LONG_BYTES:])


def our_boot_over_the_table(blob):
    """THE RUN ITSELF, made now (never served: who ran is read off its profile) — an `OurBootOverTheTable`."""
    aes_event.vet_the_profile_is_free("the staged our-boot over the table")
    emu.prof_reset()
    boot = aes_boot.booted.__wrapped__(aes_boot.preinit(), aes_boot.blank_disk(), ours=staged_for_an_our_boot(blob), laid=aes_boot.AT_GEM_ENTRY)
    defined, copy = symbols_of(blob), aes.AES_LINEF_COPY
    thunks = [defined[linef_table.thunk_symbol(routine)] for routine in THUNKED]
    ours = sorted({entry.target for entry in linef_table.entries() if entry.verdict != THE_ROM_S})
    return OurBootOverTheTable(
        boot, emu.prof_cycles(blob.base, blob.end), emu.prof_cycles(*aes.AES_TEXT), emu.prof_cycles(copy, copy + aes.LINEF_COPY_BYTES),
        emu.prof_cycles(copy + HANDLER_BYTES, copy + aes.LINEF_COPY_BYTES),
        sum(emu.prof_cycles(thunk.start, thunk.start + thunk.size) for thunk in thunks),
        [thunk.name for thunk in thunks if emu.prof_cycles(thunk.start, thunk.start + WORD_BYTES)],
        [target for target in ours if rom_span_entered(target)],
        [at for at in aes_boot.line_f_words_the_oracle_does_not_trap() if emu.prof_cycles(at, at + WORD_BYTES)])


def screen_of(ram):
    return bytes(ram[vdi.SCREEN.base:vdi.SCREEN.base + vdi.SCREEN.bytes])


@pytest.mark.parametrize("blob_name", BLOBS)
def test_the_staged_our_boot_over_our_table_reaches_the_desk_s_first_idle_with_the_rom_s_screen_a_labelled_staging(blob_name):
    """OUR gem_entry boots the blank disk; the ROM's desk — its own text, the ROM's by declaration — draws the desktop
    THROUGH OUR TABLE over our AES and parks at OUR dispatcher's idle. THE SCREEN IS THE ROM'S OWN BOOT'S, BYTE FOR
    BYTE, and the our-boot machine's with the ROM's table. WHO RAN: no ROM routine the table makes ours was entered;
    thunks were; the handler's copy ran, its tail never.
    RISK 9, AS IT STANDS UNDER THE STAGING: gem_entry's copy took the staged operand to `$cc24` and, behind the
    handler, the nine and a half longwords `gemstart.S` holds there — THE ROM'S, dead data, byte-equal to the ROM's
    own machine; our table is indexed where the blob holds it and no byte of it is copied."""
    blob = rom_bench.RomBench(*([BLOBS[blob_name]] if BLOBS[blob_name] else []))
    made = our_boot_over_the_table(blob)
    boot = made.boot
    assert boot.idle == aes_boot.OURS, f"the boot ended at {boot.idle}'s idle"
    the_rom_s = aes_boot.booted(aes_boot.preinit(), aes_boot.blank_disk())
    over_the_rom_s_table = aes_boot.booted(aes_boot.preinit(), aes_boot.blank_disk(), ours=aes_boot.ours_of(blob), laid=aes_boot.AT_GEM_ENTRY)
    assert screen_of(boot.ram) == screen_of(the_rom_s.ram), "the screen is not the ROM's own boot's"
    assert screen_of(boot.ram) == screen_of(over_the_rom_s_table.ram)
    assert any(screen_of(boot.ram)) and the_rom_s.idle == aes_boot.THE_ROM_S
    assert case.long_in(boot.ram, TABLE_OPERAND_IN_RAM) == blob.entry(TABLE)
    assert case.long_in(over_the_rom_s_table.ram, TABLE_OPERAND_IN_RAM) == aes.AES_LINEF_TABLE
    tail = slice(aes.AES_LINEF_COPY + HANDLER_BYTES, aes.AES_LINEF_COPY + aes.LINEF_COPY_BYTES)
    assert boot.ram[tail] == the_rom_s.ram[tail] == bytes(BASE_IMAGE[aes.AES_LINEF_TABLE:addrs.AES_ROM_LINEF_COPY_END])
    assert not made.in_the_copy_s_tail and made.in_the_copy and made.in_thunks and made.thunks_entered
    assert not made.rom_routines_of_ours_entered, (
        f"ROM routines the table makes ours were entered: {[hex(target) for target in made.rom_routines_of_ours_entered]}")
    cut = boot.our_boot.ran
    assert cut[1:] == (0, 0) and made.in_the_blob > cut[0], "nothing of ours ran from deskmain's entry on"
    assert not made.move16_sites, "the boot passed a Line-F word the oracle executes as MOVE16"


